326	class ExperimentTree {
327	public:
328	    explicit ExperimentTree(std::shared_ptr<AbstractNodeFactory> factory) : factory_{std::move(factory)} {
329	        root_ = std::make_unique<TreeNode>();
330	    }
331	
332	    /// Baut aus dem ZUSAMMENHÄNGENDEN Gesamt-Level-Satz (statische + dynamische Ebenen). Speichert NUR die
333	    /// Ebenen-Metadaten (statisch/dynamisch gefiltert) — es wird KEIN ∏-großer Knotenbaum materialisiert
334	    /// (User 2026-06-02: nie der ganze Baum, nur ein Pfad zur Zeit; Doc 26 §5: zählen statt materialisieren).
335	    void build(std::vector<AxisLevel> const& all_levels) {
336	        all_levels_    = all_levels;
337	        static_levels_ = static_filter();
338	        dynamic_dims_  = dynamic_filter();
339	    }
340	
341	    /// FILTER: statische Ebenen (Binary-Identität).
342	    [[nodiscard]] std::vector<AxisLevel> static_filter() const {
343	        std::vector<AxisLevel> out;
344	        for (auto const& l : all_levels_)
345	            if (l.is_static) out.push_back(l);
346	        return out;
347	    }
348	    /// FILTER: dynamische Dimensionen (virtuelle for-Schleifen).
349	    [[nodiscard]] std::vector<DynamicDim> dynamic_filter() const {
350	        std::vector<DynamicDim> out;
351	        for (auto const& l : all_levels_)
352	            if (!l.is_static) out.push_back(DynamicDim{l.axis, l.variable, l.values, l.block_id});
353	        return out;
354	    }
355	
356	    [[nodiscard]] TreeNode const& root() const { return *root_; }
357	
358	    /// Kardinalität der statischen Binaries = ∏ der statischen Ebenen-Größen — REIN ARITHMETISCH (Doc 26 §5),
359	    /// OHNE Materialisierung (== ∏ mp_size(Enabled_i) == PermutationEngine::count(), Doc 27 §6).
360	    [[nodiscard]] std::size_t binary_count() const {
361	        if (static_levels_.empty()) return 0;
362	        std::size_t n = 1;
363	        for (auto const& l : static_levels_) n *= l.values.size();
364	        return n;
365	    }
366	
367	    /// LAZY Iteration über die Binary-Blätter: materialisiert je Schritt EINEN Pfad Wurzel→Blatt (mixed-radix
368	    /// Odometer, O(Tiefe) Speicher) und ruft visitor(binary_id, pinned_signature, leaf). `leaf` ist ein
369	    /// temporäres Blatt-Objekt (key=binary_id, value=sparse NodeValue), gültig NUR während des Aufrufs.
370	    /// ⚠️ O(∏) Zeit — nur auf handhabbaren (Pilot-)Bäumen voll durchlaufen; für riesige Inventare zählt
371	    /// binary_count() / greift static_binary_view()[i] indiziert zu.
372	    template <class Visitor>
373	    void for_each_binary(Visitor&& v) const {
374	        if (static_levels_.empty()) return;
375	        for (auto const& l : static_levels_)
376	            if (l.values.empty()) return; // leere Ebene → 0 Binaries
377	        std::vector<std::size_t> idx(static_levels_.size(), 0);
378	        for (;;) {
379	            std::string bin, pin;
380	            for (std::size_t d = 0; d < static_levels_.size(); ++d) {
381	                auto const& l   = static_levels_[d];
382	                std::string seg = l.axis;
383	                seg += '=';
384	                seg += l.values[idx[d]];
385	                if (!bin.empty()) bin += '/';
386	                bin += seg;
387	                if (l.values.size() == 1) {
388	                    if (!pin.empty()) pin += '/';
389	                    pin += seg;
390	                }
391	            }
392	            TreeNode leaf;
393	            leaf.key = bin;
394	            if (auto it = value_map_.find(bin); it != value_map_.end()) leaf.value = it->second;
395	            v(bin, pin, static_cast<TreeNode const&>(leaf));
396	            std::size_t d     = static_levels_.size();
397	            bool        carry = true;
398	            while (d-- > 0) {
399	                if (++idx[d] < static_levels_[d].values.size()) {
400	                    carry = false;
401	                    break;
402	                }
403	                idx[d] = 0;
404	            }
405	            if (carry) break;
406	        }
407	    }
408	    [[nodiscard]] std::size_t binary_count_traversed() const {
409	        std::size_t n = 0;
410	        for_each_binary([&](std::string const&, std::string const&, TreeNode const&) { ++n; });
411	        return n;
412	    }
413	
414	    /// Bidirektionalität (User 2026-06-02): besucht EINEN Repräsentanten-Knoten je Achse (statische Ebene +
415	    /// dynamische Dim) — über kind()/block_id()/axis() sind die Achsen-BLÖCKE auf dem Gesamtbaum filter-/zuordbar
416	    /// (z.B. „alle Knoten des Blocks X"). EIN Knoten je Achse (Block-Struktur), NICHT ∏ (kein OOM). visitor(INodeDescription const&).
417	    template <class Visitor>
418	    void for_each_node(Visitor&& v) const {
419	        for (auto const& l : static_levels_) {
420	            if (l.values.empty()) continue;
421	            auto node = factory_->make_static(l.axis, l.values.front(), l.values.size() == 1, l.block_id);
422	            v(static_cast<INodeDescription const&>(*node));
423	        }
424	        for (auto const& d : dynamic_dims_) {
425	            if (d.values.empty()) continue;
426	            auto node = factory_->make_dynamic(d.axis, d.variable, d.values.front(), d.block_id);
427	            v(static_cast<INodeDescription const&>(*node));
428	        }
429	    }
430	
431	    /// VIRTUELL: je Binary × geschachtelte for-Schleifen über dynamic_dims_ → je Kombination eine
432	    /// ExperimentSetting (= das Blatt). visitor(ExperimentSetting const&). ⚠️ O(∏) — Pilot/Limit-Nutzung.
433	    template <class Visitor>
434	    void for_each_experiment_setting(Visitor&& v) const {
435	        for_each_binary([&](std::string const& bin, std::string const& pin, TreeNode const&) {
436	            std::vector<std::string> assign;
437	            expand(bin, pin, 0, assign, v);
438	        });
439	    }
440	    [[nodiscard]] std::size_t experiment_setting_count() const {
441	        std::size_t n = binary_count();
442	        for (auto const& d : dynamic_dims_) n *= d.values.size(); // ∏ — arithmetisch, ohne Materialisierung
443	        return n;
444	    }
445	
446	    /// KF-15: multimap<pinned signature, binary_id> — Paper-Wiedererkennung. ⚠️ O(∏) + ∏ Einträge: nur auf
447	    /// handhabbaren Bäumen aufrufen (die inverse Auswertung projiziert real GEMESSENE Blätter, Doc 26 §3).
448	    [[nodiscard]] std::multimap<std::string, std::string> pinned_signature_index() const {
449	        std::multimap<std::string, std::string> idx;
450	        for_each_binary(
451	            [&](std::string const& bin, std::string const& pin, TreeNode const&) { idx.emplace(pin, bin); });
452	        return idx;
453	    }
454	
455	    /// KF-16: LAZY indizierte Sicht auf den statischen Teilbaum (alle zu bauenden Tier-Binaries, geordnet).
456	    /// Hält NUR die Ebenen — operator[](i) dekodiert je Binary on-demand; der Build-Orchestrator materialisiert
457	    /// nur so viele Pfade gleichzeitig wie zulässige DLL-Build-Prozesse (User 2026-06-02).
458	    [[nodiscard]] StaticBinaryView static_binary_view() const { return StaticBinaryView{static_levels_}; }
459	
460	    // ── §2 per-node Observer-Statistics: SPARSE (nur GEMESSENE Binaries; BR-3) ──
461	    /// Setzt/aktualisiert die Mess-Auswertung EINES gemessenen Binary-Pfads (key = binary_id). Nur gemessene
462	    /// Pfade haben einen Eintrag — NIE alle ∏ (OOM-sicher).
463	    void set_node_value(std::string const& binary_id, NodeValue const& value) { value_map_[binary_id] = value; }
464	    [[nodiscard]] NodeValue node_value(std::string const& binary_id) const {
465	        auto it = value_map_.find(binary_id);
466	        return it == value_map_.end() ? NodeValue{} : it->second;
467	    }
468	    [[nodiscard]] std::size_t measured_node_count() const noexcept { return value_map_.size(); }
469	
470	    /// Zerlegt einen serialisierten Static-Pfad ("achse=wert/achse=wert/…") in (achse, wert)-Paare.
471	    [[nodiscard]] static std::vector<std::pair<std::string, std::string>> parse_axes(std::string const& path) {
472	        std::vector<std::pair<std::string, std::string>> out;
473	        std::size_t                                      i = 0;
474	        while (i < path.size()) {
475	            std::size_t slash = path.find('/', i);
476	            std::string seg   = path.substr(i, (slash == std::string::npos ? path.size() : slash) - i);
477	            std::size_t eq    = seg.find('=');
478	            if (eq != std::string::npos) out.emplace_back(seg.substr(0, eq), seg.substr(eq + 1));
479	            if (slash == std::string::npos) break;
480	            i = slash + 1;
481	        }
482	        return out;
483	    }
484	
485	private:
486	    template <class Visitor>
487	    void expand(std::string const& bin, std::string const& pin, std::size_t dim, std::vector<std::string>& assign,
488	                Visitor& v) const {
489	        if (dim >= dynamic_dims_.size()) {
490	            ExperimentSetting s;
491	            s.binary_id          = bin;
492	            s.pinned_signature   = pin;
493	            s.dynamic_assignment = assign;
494	            s.setting_id         = bin;
495	            s.binary_node        = nullptr; // lazy: kein persistenter Baum-Knoten
496	            for (auto const& seg : assign) {
497	                s.setting_id += "/";
498	                s.setting_id += seg;
499	            }
500	            v(s);
501	            return;
502	        }
503	        DynamicDim const& d = dynamic_dims_[dim];
504	        for (auto const& val : d.values) {
505	            auto node = factory_->make_dynamic(d.axis, d.variable, val, d.block_id); // EIN dyn. Knoten zur Zeit
506	            assign.push_back(node->serialize());
507	            expand(bin, pin, dim + 1, assign, v);
508	            assign.pop_back();
509	        }
510	    }
511	
512	    std::shared_ptr<AbstractNodeFactory> factory_;
513	    std::unique_ptr<TreeNode>            root_;          // leere Wurzel (kein materialisierter Voll-Baum)
514	    std::vector<AxisLevel>               static_levels_; // gefilterte statische Ebenen (für lazy Iteration)
515	    std::vector<DynamicDim>              dynamic_dims_;  // virtuelle dynamische for-Schleifen
516	    std::vector<AxisLevel>               all_levels_;    // zusammenhängender Gesamt-Level-Satz (vor Filterung)
517	    std::map<std::string, NodeValue>     value_map_;     // §2 SPARSE: key=binary_id → NodeValue (nur gemessene)
518	};
519	
520	} // namespace comdare::cache_engine::builder::experiment
